{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Linezolid, the closest analogue (Morgan 0.4507), has approximately 100% absolute oral bioavailability in humans after oral dosing; the query shares the oxazolidinone core and N-aryl morpholine-like substituent, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "YH4808, a close oxazolidinone analogue with a thiomorpholine ring, has low absolute bioavailability (10.1%); this is contradictory, but the thiomorpholine modification is absent in the query, limiting transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C28"],
      "claim": "Delpazolid, another oxazolidinone, shows 99.75% absolute oral bioavailability in healthy volunteers, indicating that oxazolidinones with polar heteroaryl substituents can be essentially fully absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Contezolid, an oxazolidinone with a different heteroaryl side chain, has F=0.64 in healthy subjects, still well above the 20% threshold and supportive of high bioavailability for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Cadazolid, a structurally distant oxazolidinone-quinolone hybrid, has very low oral bioavailability; its low similarity to the query limits the weight of this contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an oxazolidinone closely related to linezolid; the highest-transfer evidence shows essentially complete oral bioavailability for linezolid, and other oxazolidinones (delpazolid, contezolid) also exceed the 20% threshold. The only close low-F analogue (YH4808) has a thiomorpholine modification not present in the query, limiting transfer. Overall evidence supports F >= 20%.",
  "evidence_gaps": [
    "No direct human PK or absolute F measurement for the exact query molecule.",
    "The mechanism underlying YH4808's low F is not reported, so its relevance to the morpholinone-containing query is uncertain.",
    "Fed-state effects on absorption extent are not explicitly reported for the analogues; linezolid's extent is unaffected by food, but query-specific food interaction is unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

